//! isolate-proto — tonic/prost generated gRPC stubs.
//!
//! Re-exports all generated code from the protobuf definitions in `proto/`.
//! Generated by `build.rs` via `tonic-build` when `protoc` is installed.
//!
//! To generate:
//!   brew install protobuf
//!   cargo build -p isolate-proto
//!
//! Usage:
//!   ```ignore
//!   use isolate_proto::isolate_v1::isolate_service_client::IsolateServiceClient;
//!   ```

/// Generated code for `proto/isolate.proto`
pub mod isolate_v1 {
    #![allow(clippy::all, unused)]
    // Include generated code if protoc ran; otherwise empty module
    include!(concat!(env!("OUT_DIR"), "/isolate.v1.rs"));
}

/// Generated code for `proto/events.proto`
pub mod events_v1 {
    #![allow(clippy::all, unused)]
    include!(concat!(env!("OUT_DIR"), "/isolate.events.v1.rs"));
}

/// Generated code for `proto/intelligence.proto`
pub mod intel_v1 {
    #![allow(clippy::all, unused)]
    include!(concat!(env!("OUT_DIR"), "/isolate.intel.v1.rs"));
}
